    patterns = []
    for raw in text.splitlines():
        line = raw.strip()
        if not line:
            continue
        negated = line.startswith("!")
        if negated:
            line = line[1:]
            if not line:
                continue
        dir_only = line.endswith("/")
        if dir_only:
            line = line[:-1]
            if not line:
                continue
        anchored = "/" in line
        if anchored and line.startswith("/"):
            line = line[1:]
            if not line:
                continue
        segments = line.split("/")
        if not anchored:
            segments = ["**"] + segments
        regex = _compile(segments)
        patterns.append((regex, negated, dir_only))
    return patterns


def _compile(segments):
    parts = []
    for i, seg in enumerate(segments):
        if seg == "**":
            if i == 0:
                parts.append("(?:[^/]+(?:/[^/]+)*)?")
            else:
                parts.append("(?:/[^/]+)*")
        else:
            if i > 0 and segments[i - 1] != "**":
                parts.append("/")
            elif i > 0:
                parts.append("/")
            parts.append(_seg_regex(seg))
    return re.compile("".join(parts) + r"\Z", re.DOTALL)


